1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Step of {@code POST /api/owners}: records on the owner the number of existing owners that
11	 * already share its first name and last name, compared case-insensitively. Counts the owners
12	 * present before this create (the new owner is not yet saved) and mutates the built owner in
13	 * place before it is persisted.
14	 */
15	public class CountNamesakes {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = normalize(owner.getFirstName());
19	        String lastName = normalize(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (firstName.equals(normalize(existing.getFirstName()))
23	                    && lastName.equals(normalize(existing.getLastName()))) {
24	                count++;
25	            }
26	        }
27	        owner.setNamesakeCount(count);
28	    }
29	
30	    private static String normalize(String value) {
31	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
32	    }
33	}
