8	/**
9	 * Emits an audit line to the dedicated {@code AUDIT} logger for a successfully created owner,
10	 * carrying the owner id, the {@code customerCode} and the {@code registrationDate}. Runs after
11	 * the owner has been saved (so the generated id is available) and before the response is sent.
12	 */
13	public class LogOwnerAudit {
14	
15	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
