15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "membershipNumber",
27	        expression = "java(owner.getCustomerCode() + \"-M\" "
28	            + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
29	    @Mapping(target = "membershipTier",
30	        expression = "java(owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3 ? \"GOLD\" "
31	            + ": (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 "
32	            + "&& owner.getEmail() != null && !owner.getEmail().isBlank() ? \"SILVER\" : \"BRONZE\"))")
33	    @Mapping(target = "locality",
34	        expression = "java(org.springframework.samples.petclinic.mapper.Locality.of(owner.getCity()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    @Mapping(target = "id", ignore = true)
40	    @Mapping(target = "pets", ignore = true)
41	    Owner toOwner(OwnerFieldsDto ownerDto);
42	
43	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
44	
45	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
46	
47	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
48	        OwnerPageDto ownerPageDto = new OwnerPageDto();
49	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
50	        ownerPageDto.setPage(ownerPage.getNumber());
51	        ownerPageDto.setSize(ownerPage.getSize());
52	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
53	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
54	        return ownerPageDto;
55	    }
56	}
