1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners}: records on the owner the size of its household after this
9	 * create — the number of owners sharing its {@code householdId} once the new owner is included.
10	 * Runs after {@link AssignHouseholdId} (which stamps the shared identifier on the new owner and
11	 * its existing housemates) and before the owner is persisted, so it counts the existing members
12	 * carrying the same {@code householdId} plus the new owner itself.
13	 *
14	 * <p>A membership tier of {@code GOLD} is derived from this count (3 or more members); an owner
15	 * with no household leaves it null so the standard BRONZE/SILVER rules apply.
16	 */
17	public class CountHouseholdMembers {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            return;
23	        }
24	        int count = 1; // the new owner, not yet persisted
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (householdId.equals(existing.getHouseholdId())) {
27	                count++;
28	            }
29	        }
30	        owner.setHouseholdSize(count);
31	    }
32	}
